import{workflowToolRunWorkflowReference}from"#execution/workflow-references.js";import{startWorkflowOnCurrentDeployment}from"#execution/workflow-runtime.js";import{workflowToolRunHookToken}from"#execution/tools/workflow/start.js";const startWorkflowToolRun=async e=>{let t=workflowToolRunHookToken(e);return{hookToken:t,runId:(await startWorkflowOnCurrentDeployment(workflowToolRunWorkflowReference,[{...e,hookToken:t}])).runId}};export{startWorkflowToolRun};