import{isRunTargetGone}from"#shared/run-errors.js";import{resumeRoutedHook,routedRunEnded}from"#execution/hosts.js";import{pollUntil}from"#shared/poll-until.js";const INTERRUPT={kind:`interrupt`};const RUN_START_TIMEOUT_MS=3e4;async function interruptWorkflowToolRun(e){"use step";if(await pollUntil(async()=>{try{return await resumeRoutedHook(e.hookToken,INTERRUPT),!0}catch(e){if(!isRunTargetGone(e))throw e}return await routedRunEnded(e.runId)?!0:void 0},RUN_START_TIMEOUT_MS)===void 0)throw Error(`Workflow tool run "${e.runId}" did not start taking commands within ${RUN_START_TIMEOUT_MS/1e3} seconds, so it has not received the interrupt yet.`)}export{interruptWorkflowToolRun};