import{SandboxKey}from"#context/keys.js";import{createLogger}from"#internal/logging.js";import{withContextScope}from"#context/run-step.js";import{deserializeContext}from"#context/serialize.js";import{readDurableSession,replaceDurableSessionSnapshot}from"#execution/durable-session-store.js";import{clearSandboxRunning}from"#sandbox/state.js";import{hydrateDurableSession}from"#execution/session.js";import{withSessionStateDelta}from"#execution/session/step-state-delta.js";const log=createLogger(`execution.session.idle-sandbox`);const IDLE_STOP_TIMEOUT_MS=12e4;async function withinIdleStopTimeout(e){let t=new AbortController;let n;let r=new Promise((e,r)=>{n=setTimeout(()=>{let e=Error(`The sandbox provider did not stop the idle sandbox within ${IDLE_STOP_TIMEOUT_MS/1e3} seconds.`);t.abort(e),r(e)},IDLE_STOP_TIMEOUT_MS)});try{await Promise.race([e(t.signal),r])}finally{clearTimeout(n)}}async function stopIdleSessionSandboxStep(e){"use step";return await withSessionStateDelta(e,stopIdleSessionSandbox)}async function stopIdleSessionSandbox(e){let t=readDurableSession(e.sessionState);try{let n=await deserializeContext(e.serializedContext);await withContextScope(n,hydrateDurableSession(t),async e=>{let t=n.get(SandboxKey);return t!==void 0&&await withinIdleStopTimeout(e=>t.stopIdle({signal:e})),{result:void 0,session:e}})}catch(t){log.warn(`failed to stop an idle session sandbox; the provider's own timeout still applies`,{error:t,sessionId:e.sessionState.sessionId})}return{sessionState:replaceDurableSessionSnapshot({session:{...t,sandboxState:clearSandboxRunning(t.sandboxState)},state:e.sessionState})}}export{stopIdleSessionSandboxStep};