import{createSession,projectToDurableSession}from"#execution/session.js";import{DURABLE_SESSION_VERSION}from"#execution/durable-session-read.js";import{withPendingHistory}from"#execution/session/pending-history.js";function createInitialSessionValues(e){let t=createSession({continuationToken:e.continuationToken,outputSchema:e.outputSchema,rootSessionId:e.rootSessionId,sessionId:e.sessionId});let n=withPendingHistory(t.state,e.history);let r=projectToDurableSession(n===t.state?t:{...t,state:n});return{history:t.history,state:{continuationToken:r.continuationToken,hasProxyInputRequests:!1,sessionId:r.sessionId,version:DURABLE_SESSION_VERSION,snapshot:{session:r}}}}export{createInitialSessionValues};