import{createLogger,logError}from"#internal/logging.js";import{SessionStrandedError}from"#channel/session-stranded-error.js";import{NonRetryableError}from"#shared/run-errors.js";import{agentDelegation}from"#tracing/eve/delegation.js";import{agentSessionResetCommand,localAgentSendCommand,prepareLocalAgentSession,resolveAgentSessionStart}from"#execution/agent-sessions/start.js";import{cancelRemoteSessionTurn,endRemoteSession,sendRemoteSessionMessage,startRemoteSession}from"#execution/agent-sessions/remote-session.js";const log=createLogger(`execution.agent-sessions`);function agentSessionsOver(e){let{local:t}=e;let remoteAccess=t=>{if(e.remote!==void 0)return e.remote;throw new NonRetryableError(`Agent "${t}" is remote, and this host can't reach remote agents yet. Run the agent with \`eve dev\` or deploy it.`)};let end=async n=>{let{address:r,context:i}=n;try{if(r.kind===`remote`){await endRemoteSession(i,r);return}await t.command({...n,address:r},agentSessionResetCommand(e.deliveryId(`reset`,r.sessionId)))}catch(e){logError(log,`failed to end an agent session`,e,{name:r.name,sessionId:r.sessionId})}};return{async open(e){let n=await resolveAgentSessionStart(e);let{target:r}=n;return await agentDelegation.resume({context:e.context,agentName:n.agentName},()=>r.kind===`remote`?startRemoteSession({...n,target:r},{callbackBaseUrl:remoteAccess(n.agentName).callbackBaseUrl(),operationId:`agent-session:${n.key}`}):t.start(prepareLocalAgentSession({...n,target:r}),n))},async send(n){let{address:r}=n;let i=e.deliveryId(`send`,r.sessionId);if(r.kind===`remote`)return await sendRemoteSessionMessage({...n,address:r},i);let a=await t.command({...n,address:r},localAgentSendCommand({...n,address:r},i)).catch(e=>{throw SessionStrandedError.is(e)?Error(`Agent "${r.name}" can no longer receive messages: ${e.message}`,{cause:e}):e});if(a.status!==`accepted`)throw Error(`Agent "${r.name}" can no longer receive messages; its session ended.`);return{deliveryId:i,sessionId:a.sessionId}},async cancelTurn(n){let{address:r,context:i}=n;try{if(r.kind===`remote`){await cancelRemoteSessionTurn(i,r);return}await t.command({...n,address:r},{kind:`cancel`,deliveryId:e.deliveryId(`cancel`,r.sessionId)})}catch(e){logError(log,`failed to cancel an agent session turn`,e,{name:r.name,sessionId:r.sessionId})}},async end({sessions:e}){await Promise.all(e.map(end))},async stopLate(n){if(n.address.kind===`remote`){await end(n);return}let{sessionId:r}=n.address;try{await t.commandLate(r,agentSessionResetCommand(e.deliveryId(`reset`,r)))}catch(e){logError(log,`could not stop late child; cleanup is best effort`,e,{sessionId:r})}}}}export{agentSessionsOver};