import{credentialFailureCode,refusesCredential}from"./errors.js";import{displayProperName}from"#protocol/session-projection/display-name.js";import{stopForSignIn}from"#harness/hitl/index.js";import{isConnectionAuthorizationFailedError}from"#connections/errors.js";import{handleAuthorizationError}from"#runtime/connections/scoped-authorization.js";import{supportsInteractiveAuthorization}from"#shared/connection-types.js";import{SIGN_IN_DECLINED}from"#harness/hitl/sign-ins.js";import{failTurn}from"#harness/step/context.js";async function pauseForModelSignIn(e,t,n){if(!supportsInteractiveAuthorization(t.scoped.authorization))return await failModelCredential(e,`MODEL_AUTHORIZATION_FAILED`,t.cause,t.scoped);let r;try{r=await handleAuthorizationError(t,{evictToken:!1})}catch(n){return await failModelCredential(e,credentialFailureCode(n),n,t.scoped)}return await n?.(),await stopForSignIn(e,r)}async function failModelCredential(e,t,n,r){let i=providerName(e.view(),r);return await failTurn(e,n,t,credentialFailureMessage(t,i,n))}function credentialFailureMessage(e,t,n){switch(e){case`MODEL_AUTHORIZATION_FAILED`:return signInFailureMessage(t,n);case`MODEL_CREATE_FAILED`:return`eve couldn't build the model from the ${t} credential.`;case`MODEL_CREDENTIAL_FAILED`:return`eve couldn't get the ${t} credential.`}}function signInFailureMessage(e,t){if(!isConnectionAuthorizationFailedError(t))return refusesCredential(t)?`${e} rejected the credential.`:`The turn got no ${e} credential.`;switch(t.reason){case SIGN_IN_DECLINED:case`sign_in_cancelled`:return`The ${e} sign-in ended without a credential.`;case`sign_in_unavailable`:return`A scheduled turn can't ask for the ${e} sign-in.`;case`principal_required`:return`The ${e} credential needs a signed-in user.`;case`token_rejected_after_authorization`:return`${e} rejected the credential from the sign-in.`;case`app_not_installed`:case`authorization_callback_unavailable`:return`The turn got no ${e} credential.`;default:return`${e}: ${t.message}`}}function providerName(e,t){let n=Object.values(e.projection.view.interactions).flatMap(e=>e.request.signIn??[]).findLast(e=>e.name===t.scope);return t.authorization.displayName??n?.displayName??displayProperName(t.scope)}export{failModelCredential,pauseForModelSignIn};