import{ModelCredentialFailure,credentialFailureCode}from"./errors.js";import{wrapLanguageModel}from"ai";import{isRuntimeLanguageModel}from"#internal/runtime-model.js";import{isDefinedModel,modelSignInName}from"#models/definition.js";import{createAuthorizationExecution,evictScopedToken,isScopedAuthorizationRequiredError}from"#runtime/connections/scoped-authorization.js";async function credentialedModel(e){if(!isDefinedModel(e))return{model:e};let t=createAuthorizationExecution();let n=scopedAuthorization(e);let create=async()=>createdModel(e,await credentialFor(t,n),n);let r=await create();let i=!1;return{model:wrapLanguageModel({middleware:{wrapGenerate:({params:e})=>r.doGenerate(e),wrapStream:({params:e})=>r.doStream(e)},model:r}),scoped:n,async renew(e){await evictScopedToken(n),i&&t.requireAuth(n,e),i=!0,r=await create()}}}function scopedAuthorization(e){return{authorization:e.auth,connection:{url:``},scope:modelSignInName(e)}}async function credentialFor(e,t){try{return await e.getToken(t)}catch(e){throw isScopedAuthorizationRequiredError(e)?e:new ModelCredentialFailure(credentialFailureCode(e),t,e)}}function createdModel(e,t,n){try{let n=e.create(t);if(!isRuntimeLanguageModel(n))throw Error(`create returned no language model.`);return wrapLanguageModel({middleware:{},model:n})}catch(e){throw new ModelCredentialFailure(`MODEL_CREATE_FAILED`,n,e)}}export{credentialedModel};